<?php
namespace ExcelHerbal\ERP7\Finance;
use ExcelHerbal\ERP7\Core\Input;use ExcelHerbal\ERP7\Database\Db;use ExcelHerbal\ERP7\Database\Transaction;use ExcelHerbal\ERP7\Domain\DomainException;use ExcelHerbal\ERP7\Inventory\StockService;use ExcelHerbal\ERP7\Security\Actor;use ExcelHerbal\ERP7\Security\Audit;use ExcelHerbal\ERP7\Security\Capabilities;use ExcelHerbal\ERP7\Security\Guard;
final class FinanceClosingService{
 public static function closings(Actor $a,int $branch):array{Guard::branch($a,$branch,$a->can(Capabilities::BRANCH_CLOSE)?Capabilities::BRANCH_CLOSE:Capabilities::BRANCH_REOPEN);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT * FROM ".Db::table('branch_closings')." WHERE company_id=%d AND branch_id=%d ORDER BY business_date DESC,id DESC LIMIT 200",$a->companyId,$branch),ARRAY_A);}
 public static function closingPreflight(Actor $a,int $branch,string $date):array{$date=Input::date($date,'Business date');Guard::branch($a,$branch,Capabilities::BRANCH_CLOSE);$db=Db::wpdb();$checks=['daily_cycles_open'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('daily_cycles')." WHERE company_id=%d AND branch_id=%d AND business_date=%s AND status NOT IN ('completed','cancelled')",$a->companyId,$branch,$date)),'transfers_open'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_transfers')." WHERE company_id=%d AND (source_branch_id=%d OR destination_branch_id=%d) AND status NOT IN ('received','cancelled')",$a->companyId,$branch,$branch)),'adjustments_pending'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_adjustments')." WHERE company_id=%d AND branch_id=%d AND status='pending'",$a->companyId,$branch)),'quarantine_open'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_quarantine')." WHERE company_id=%d AND branch_id=%d AND status='open'",$a->companyId,$branch)),'expenses_pending'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('expenses')." WHERE company_id=%d AND branch_id=%d AND status='pending' AND expense_date<=%s",$a->companyId,$branch,$date)),'reversals_pending'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('reversals')." WHERE company_id=%d AND status IN ('pending','approved') AND (branch_id=%d OR branch_id IS NULL)",$a->companyId,$branch)),'payroll_draft'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('payroll_runs')." WHERE company_id=%d AND branch_id=%d AND status='draft' AND period_end<=%s",$a->companyId,$branch,$date)),'employee_custody_nonzero'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_balances')." WHERE company_id=%d AND branch_id=%d AND custodian_key>0 AND ABS(quantity)>.0001",$a->companyId,$branch)),'negative_stock'=>(int)$db->get_var($db->prepare("SELECT COUNT(*) FROM ".Db::table('stock_balances')." WHERE company_id=%d AND branch_id=%d AND quantity<-.0001",$a->companyId,$branch))];$blocking=array_keys(array_filter($checks,fn($v)=>(int)$v>0));return['ok'=>!$blocking,'checks'=>$checks,'blocking'=>$blocking];}
 public static function closingDraft(Actor $a,int $branch,string $date):array{$date=Input::date($date,'Business date');Guard::branch($a,$branch,Capabilities::BRANCH_CLOSE);return Transaction::run(function()use($a,$branch,$date){$db=Db::wpdb();$branchTable=Db::table('branches');$locked=$db->get_var($db->prepare("SELECT id FROM {$branchTable} WHERE id=%d AND company_id=%d AND status='active' FOR UPDATE",$branch,$a->companyId));if(!$locked)throw new DomainException('Active branch not found.','branch_not_found',404);$t=Db::table('branch_closings');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE company_id=%d AND branch_id=%d AND business_date=%s FOR UPDATE",$a->companyId,$branch,$date),ARRAY_A);if($r)return['id'=>(int)$r['id'],'status'=>$r['status']];Db::mustInsert($db,$t,['company_id'=>$a->companyId,'branch_id'=>$branch,'business_date'=>$date,'status'=>'draft','created_by'=>$a->employeeId,'created_at'=>Db::now()]);$id=(int)$db->insert_id;Audit::add($a,'branch_closing.draft','branch_closing',$id,['branch_id'=>$branch,'business_date'=>$date]);return['id'=>$id,'status'=>'draft'];});}
 public static function closeBranch(Actor $a,int $id):array{return Transaction::run(function()use($a,$id){$db=Db::wpdb();$t=Db::table('branch_closings');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d FOR UPDATE",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Branch closing not found.','closing_not_found',404);Guard::branch($a,(int)$r['branch_id'],Capabilities::BRANCH_CLOSE);if((int)$r['created_by']===$a->employeeId)throw new DomainException('Maker cannot close own draft.','maker_checker_required',409);$pf=self::closingPreflight($a,(int)$r['branch_id'],(string)$r['business_date']);if(!$pf['ok'])throw new DomainException('Closing blocked: '.implode(', ',$pf['blocking']),'closing_blocked',409);Db::mustUpdate($db,$t,['status'=>'closed','preflight_json'=>wp_json_encode($pf),'closed_by'=>$a->employeeId,'closed_at'=>Db::now()],['id'=>$id]);Audit::add($a,'branch_closing.close','branch_closing',$id,['branch_id'=>(int)$r['branch_id'],'business_date'=>(string)$r['business_date']]);return['id'=>$id,'status'=>'closed','preflight'=>$pf];});}
 public static function reopenBranch(Actor $a,int $id,string $reason):array{Guard::cap($a,Capabilities::BRANCH_REOPEN);if(strlen(trim($reason))<5)throw new DomainException('Reopen reason required.');$db=Db::wpdb();$t=Db::table('branch_closings');$r=$db->get_row($db->prepare("SELECT * FROM {$t} WHERE id=%d AND company_id=%d",$id,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Closing not found.');Guard::branch($a,(int)$r['branch_id'],Capabilities::BRANCH_REOPEN);if($r['status']!=='closed')throw new DomainException('Only closed day can reopen.');Db::mustUpdate($db,$t,['status'=>'reopened','reopened_by'=>$a->employeeId,'reopened_at'=>Db::now()],['id'=>$id]);Audit::add($a,'branch_closing.reopen','branch_closing',$id,['branch_id'=>(int)$r['branch_id'],'reason'=>$reason]);return['id'=>$id,'status'=>'reopened'];}
}
